return $input.all().flatMap(({ json }, index) => {
  const from = String(json.from || '').trim();
  const sender = (from.match(/<([^<>]+)>\s*$/)?.[1] || from).toLowerCase();
  const official = /^[^\s<>@]+@(?:[a-z0-9-]+\.)*(?:avto\.pro|avtopro\.ua)$/i;
  if (!official.test(sender)) return [];
  const messageId = String(json.metadata?.['message-id'] || json.messageId || '').trim();
  if (!messageId) throw new Error('У повідомленні Автопро відсутній Message-ID');
  const subject = String(json.subject || '').trim().slice(0, 500);
  let plain = String(json.textPlain || '');
  if (!plain && json.textHtml) {
    plain = String(json.textHtml).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, '').replace(/<br\s*\/?\s*>|<\/(p|div|tr|li)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/gi, ' ').replace(/&#8470;|&#x2116;/gi, '№');
  }
  return [{ json: { sender, messageId, subject, text: plain.slice(0, 5000) }, pairedItem: { item: index } }];
});
